{
  "name": "NeuroSpect",
  "slug": "neurospect",
  "description": "AI trading intelligence platform for ICT/Smart Money traders. Data-foundation-first architecture: verified trading data, risk protection, ICT event detection, backtesting, AI coaching, forensics, scoring, rewards, advanced ML.",
  "status": "active",
  "build_order": 3,
  "created": "2026-05-23",
  "platform": "web-responsive",
  "stack": {
    "frontend": "react-19-typescript-vite-tailwind-shadcn",
    "backend": "fastapi-sqlalchemy-postgres",
    "data": "postgres-16-alembic",
    "ai": "anthropic-sdk-claude",
    "storage": "cloudflare-r2-boto3",
    "payments": "stripe",
    "monitoring": "sentry",
    "future": ["pgvector", "bm25-tsvector", "graph-db"]
  },
  "phases": [
    {
      "id": "P0",
      "name": "Marketing + Demo",
      "status": "in-progress",
      "description": "Validate market interest through interactive marketing site, live simulator, ICT course, and EdgeLab demo. Technical validation: CI/CD, Sentry, data model audit."
    },
    {
      "id": "P1",
      "name": "Trading Data Foundation",
      "status": "complete",
      "description": "Normalized, verified trading data layer. BrokerAccount model, trade extensions, instrument metadata, CSV import, Tradovate sync, data quality checks."
    },
    {
      "id": "P2",
      "name": "Trader Workspace",
      "status": "complete",
      "description": "Daily-use trader workspace: full journal, analytics dashboard, behavior metrics (tilt, discipline, consistency). Free tier engagement layer."
    },
    {
      "id": "P3",
      "name": "Prop Shield",
      "status": "complete",
      "description": "Prop firm rule tracking, trailing drawdown monitoring, tilt lockouts, advisory alerts, Stripe billing. FIRST REVENUE: Mentor $29/mo, Trader $99/mo."
    },
    {
      "id": "P4",
      "name": "ICT Event Intelligence",
      "status": "planned",
      "description": "Programmable ICT event detection: FVGs, sweeps, order blocks, market structure, sessions as queryable events. Foundation for backtesting and forensics."
    },
    {
      "id": "P5",
      "name": "EdgeLab Core",
      "status": "planned",
      "description": "Event-driven backtesting engine (5A), strategy compiler + Monte Carlo + walk-forward (5B), dashboard + null test (5C). Research tier $199/mo."
    },
    {
      "id": "P6",
      "name": "AI Trade Review + RAG",
      "status": "in-progress",
      "description": "NeuroCore hybrid retrieval (BM25 + semantic + entity) and Mentor upgrade to multi-turn chat with citations, structured trade reviews, and context injection."
    },
    {
      "id": "P7",
      "name": "Edge Forensics",
      "status": "planned",
      "description": "Loss pattern mining, mistake taxonomy, hypothesis generation. Turns repeated losses into testable EdgeLab experiments."
    },
    {
      "id": "P8",
      "name": "NeuroScore + Leaderboard",
      "status": "planned",
      "description": "Risk-adjusted trader ranking (performance, drawdown, rules, consistency, tilt). Broker-verified trades only. Quant tier $349/mo."
    },
    {
      "id": "P9",
      "name": "NeuroFund Elite Rewards",
      "status": "planned",
      "description": "Company-sponsored rewards and eligibility program. NOT pooled capital. Compliance-critical: approved language, admin review, 50-member activation threshold."
    },
    {
      "id": "P10",
      "name": "Allocation Watchlist",
      "status": "in-progress",
      "description": "Internal workflow for identifying traders for challenge sponsorships, grants, or company-sponsored allocation consideration. Trader model cards, admin review."
    },
    {
      "id": "P11",
      "name": "Advanced ML Research",
      "status": "planned",
      "description": "NSLM evaluation framework (11A), hybrid models + regime detection (11B), NeuroQuant + NeuroTrader shadow mode (11C). Gated by Phase 5C null test."
    },
    {
      "id": "P3-NG",
      "name": "NeuroGraph",
      "status": "in-progress",
      "description": "Persistent trading intelligence graph. Nodes = trades, events, features, setups, patterns, concepts. Plan-mode-first: data source mapping, schema design, seed strategy."
    }
  ]
}

{
  "name": "Labs Institute",
  "slug": "labs-institute",
  "description": "DJ artist management platform — three tiers (marketing site, owner portal, DJ portal) with AI-driven intelligence layer for self-improvement.",
  "status": "active",
  "build_order": 1,
  "created": "2026-05-23",
  "platform": "web-responsive",
  "stack": {
    "frontend": "vanilla-html-css-js",
    "backend": "python",
    "data": "json-file",
    "future": ["postgres", "vector-db", "zeus-memory"]
  },
  "tiers": {
    "marketing-site": "Public-facing labs.institute — roster showcase, services, proof of value",
    "owner-portal": "Admin dashboard — roster, venues, events, contracts, finances, bookings",
    "dj-portal": "Per-artist dashboard — content, socials, calendar, gig tracker, metrics",
    "lab-intelligence": "AI layer — vector DB, pattern detection, growth roadmaps, improvement suggestions",
    "lab-wiki": "Knowledge base — decisions, learnings, patterns, institutional knowledge",
    "chat": "Founder ↔ DJ communication with AI assistant using Lab-Intelligence + Lab-Wiki context"
  },
  "phases": [
    {
      "id": "P0",
      "name": "Site Content Builder + Marketing Page",
      "status": "in-progress",
      "description": "Conductor-based intake UI to capture all site content. Output feeds labs.institute build."
    },
    {
      "id": "P1",
      "name": "DJ Profiles + Roster (Owner Portal)",
      "status": "planned",
      "description": "DJ profiles with genre, tier, rate card, availability, socials, KPIs. Roster management dashboard."
    },
    {
      "id": "P2",
      "name": "DJ Portal — Content + Calendar",
      "status": "planned",
      "description": "Per-DJ dashboard: manage content, social links, gig calendar, track metrics."
    },
    {
      "id": "P3",
      "name": "Contracts + Booking Workflow",
      "status": "planned",
      "description": "Contract templates, booking lifecycle (inquiry → quote → contract → confirm), status tracking."
    },
    {
      "id": "P4",
      "name": "Chat + Communication Hub",
      "status": "planned",
      "description": "Founder ↔ DJ messaging. AI assistant answers questions from Lab-Wiki + Lab-Intelligence context."
    },
    {
      "id": "P5",
      "name": "Lab-Intelligence — AI Growth Engine",
      "status": "planned",
      "description": "Vector DB ingesting gig outcomes, social metrics, campaign results. Generates growth roadmaps, post-mortems, improvement suggestions."
    },
    {
      "id": "P6",
      "name": "Lab-Wiki — Knowledge Base",
      "status": "planned",
      "description": "Structured knowledge capture: what works at which venues, optimal pricing, best promo strategies. Searchable by founder and DJs."
    },
    {
      "id": "P7",
      "name": "Pricing Engine",
      "status": "planned",
      "description": "Dynamic pricing based on location, event scale, DJ tier, market data. Rate cards per DJ."
    },
    {
      "id": "P8",
      "name": "Marketing + Social Tools",
      "status": "planned",
      "description": "Content calendar, cross-platform posting, campaign tracking, audience analytics."
    },
    {
      "id": "P9",
      "name": "Gig Discovery + DJ Matching",
      "status": "planned",
      "description": "Event opportunity feed. Match DJs to gigs by genre, location, availability. Application tracking."
    },
    {
      "id": "P10",
      "name": "Financial Management",
      "status": "planned",
      "description": "Invoicing, payment tracking, commission calculator, P&L per event and per DJ."
    }
  ]
}
